from pathlib import Path

path = Path("agents/scheduler.py")
text = path.read_text()

start = text.index("_ANIMAL_SERVICE_OPS =")
end = text.index("\ndef build_queues(")

replacement = '\ndef _bucket_budget(base_budget, bucket, terminal_day):\n    """Executable budget for a bucket, including terminal cashout deadlines."""\n    if not terminal_day:\n        return base_budget\n    return max(0, base_budget - 1 - int(_cashout_needed(bucket)))\n\n\ndef _task_order(tasks, worker_starts, variant):\n    """Deterministic geometry-only seed orders.\n\n    Variants change only geometric/task-size tie breaking.  They never inspect\n    the action class, urgency flag, or crop/animal type.\n    """\n    def distance(task):\n        return min(\n            abs(start[0] - task.position[0]) + abs(start[1] - task.position[1])\n            for start in worker_starts\n        )\n\n    if variant == 1:\n        return sorted(\n            tasks,\n            key=lambda task: (\n                -distance(task), -len(task.actions),\n                task.position[1], task.position[0],\n            ),\n        )\n    if variant == 2:\n        return sorted(\n            tasks,\n            key=lambda task: (\n                task.position[0], task.position[1],\n                -len(task.actions), distance(task),\n            ),\n        )\n    if variant == 3:\n        return sorted(\n            tasks,\n            key=lambda task: (\n                task.position[1], task.position[0],\n                -len(task.actions), distance(task),\n            ),\n        )\n    return sorted(\n        tasks,\n        key=lambda task: (\n            distance(task), -len(task.actions),\n            task.position[1], task.position[0],\n        ),\n    )\n\n\ndef _pack_variant(\n    tasks,\n    worker_starts,\n    budgets,\n    shed_access=SHED_ACCESS,\n    variant=0,\n    initial_buckets=None,\n):\n    """Insert all supplied tasks using route cost only.\n\n    Task.actions already encode every within-task dependency.  This packer adds\n    no action-class ordering: a task may be inserted anywhere its complete\n    route remains feasible.\n    """\n    buckets = (\n        [list(bucket) for bucket in initial_buckets]\n        if initial_buckets is not None\n        else [[] for _ in worker_starts]\n    )\n    sheds = {}\n\n    def shed_for(position):\n        if position not in sheds:\n            sheds[position] = nearest_shed(position, shed_access)\n        return sheds[position]\n\n    terminal_day = any(\n        task.terminal_day or task.cashout\n        for task in [*tasks, *(task for bucket in buckets for task in bucket)]\n    )\n    lengths = [\n        _task_length(start, bucket, shed_for) if bucket else 0\n        for start, bucket in zip(worker_starts, buckets)\n    ]\n    unassigned = []\n\n    for task in _task_order(tasks, worker_starts, variant):\n        best = None\n        for worker, bucket in enumerate(buckets):\n            for insertion in range(len(bucket) + 1):\n                candidate_bucket = bucket[:insertion] + [task] + bucket[insertion:]\n                projected = _task_length(\n                    worker_starts[worker], candidate_bucket, shed_for\n                )\n                if projected > _bucket_budget(\n                    budgets[worker], candidate_bucket, terminal_day\n                ):\n                    continue\n                delta = projected - lengths[worker]\n                candidate = (delta, projected, worker, insertion)\n                if best is None or candidate < best:\n                    best = candidate\n        if best is None:\n            unassigned.append(task)\n            continue\n        _, projected, worker, insertion = best\n        buckets[worker].insert(insertion, task)\n        lengths[worker] = projected\n\n    return buckets, unassigned\n\n\ndef _best_optional_insertion(\n    task,\n    buckets,\n    worker_starts,\n    budgets,\n    shed_access,\n    terminal_day,\n):\n    sheds = {}\n\n    def shed_for(position):\n        if position not in sheds:\n            sheds[position] = nearest_shed(position, shed_access)\n        return sheds[position]\n\n    best = None\n    for worker, bucket in enumerate(buckets):\n        baseline = _task_length(worker_starts[worker], bucket, shed_for) if bucket else 0\n        for insertion in range(len(bucket) + 1):\n            candidate_bucket = bucket[:insertion] + [task] + bucket[insertion:]\n            projected = _task_length(\n                worker_starts[worker], candidate_bucket, shed_for\n            )\n            if projected > _bucket_budget(\n                budgets[worker], candidate_bucket, terminal_day\n            ):\n                continue\n            delta = projected - baseline\n            candidate = (delta, projected, worker, insertion)\n            if best is None or candidate < best:\n                best = candidate\n    return best\n\n\ndef _fill_optional(\n    buckets,\n    optional,\n    worker_starts,\n    budgets,\n    shed_access=SHED_ACCESS,\n):\n    """Admit optional work by economic value over incremental route cost."""\n    buckets = [list(bucket) for bucket in buckets]\n    remaining = list(optional)\n    terminal_day = any(\n        task.terminal_day or task.cashout\n        for task in [*remaining, *(task for bucket in buckets for task in bucket)]\n    )\n\n    while remaining:\n        best = None\n        for index, task in enumerate(remaining):\n            if task.value <= 0:\n                continue\n            insertion = _best_optional_insertion(\n                task, buckets, worker_starts, budgets, shed_access, terminal_day\n            )\n            if insertion is None:\n                continue\n            delta, projected, worker, at = insertion\n            route_cost = max(1, delta)\n            density = task.value / route_cost\n            candidate = (\n                -density,\n                -task.value,\n                delta,\n                task.position[1],\n                task.position[0],\n                index,\n                projected,\n                worker,\n                at,\n            )\n            if best is None or candidate < best:\n                best = candidate\n        if best is None:\n            break\n\n        (\n            _neg_density,\n            _neg_value,\n            _delta,\n            _y,\n            _x,\n            index,\n            _projected,\n            worker,\n            at,\n        ) = best\n        task = remaining.pop(index)\n        buckets[worker].insert(at, task)\n\n    return buckets, remaining\n\n\ndef _packing_score(result, tasks, worker_starts, budgets, shed_access):\n    buckets, unassigned = result\n    missing_required = sum(task.mandatory is not False for task in unassigned)\n    missing_optional_value = sum(\n        task.value for task in unassigned if task.mandatory is False\n    )\n    sheds = {}\n\n    def shed_for(position):\n        if position not in sheds:\n            sheds[position] = nearest_shed(position, shed_access)\n        return sheds[position]\n\n    total_steps = sum(\n        _task_length(start, bucket, shed_for) if bucket else 0\n        for start, bucket in zip(worker_starts, buckets)\n    )\n    return missing_required, missing_optional_value, total_steps\n\n\ndef _pack(tasks, worker_starts, budgets, shed_access=SHED_ACCESS):\n    """Build one complete daily schedule without action priorities.\n\n    Required work is a hard inclusion constraint.  Optional work is admitted\n    only after a feasible required schedule exists, and is selected by value\n    against its incremental route cost.  Several deterministic geometric seed\n    orders are compared; action names never affect execution order.\n    """\n    required = [task for task in tasks if task.mandatory is not False]\n    optional = [task for task in tasks if task.mandatory is False]\n    best = None\n    best_score = None\n\n    for variant in range(4):\n        buckets, missing_required = _pack_variant(\n            required, worker_starts, budgets, shed_access, variant\n        )\n        if missing_required:\n            candidate = (buckets, missing_required + list(optional))\n        else:\n            buckets, missing_optional = _fill_optional(\n                buckets, optional, worker_starts, budgets, shed_access\n            )\n            candidate = (buckets, missing_optional)\n\n        score = _packing_score(\n            candidate, tasks, worker_starts, budgets, shed_access\n        )\n        if best is None or score < best_score:\n            best, best_score = candidate, score\n\n    return best\n\n\ndef hands_needed(\n    tasks,\n    farmer_start,\n    existing_hand_starts=(),\n    shed_access=SHED_ACCESS,\n    pending_hand_budget=HAND_BUDGET,\n    max_hands=MAX_HANDS,\n    marginal_hire_costs=None,\n):\n    """Choose headcount from complete-schedule feasibility and economics.\n\n    Required tasks are hard constraints.  Once the smallest feasible required\n    headcount is known, extra hands are purchased only when the additional\n    optional value they admit exceeds the cumulative marginal hire cost.\n    Existing hands are sunk cost.\n    """\n    minimum = min(len(existing_hand_starts), max_hands)\n    schedulable_required = [\n        task for task in tasks\n        if task.mandatory is not False\n        and len(task.actions) <= max(\n            FARMER_BUDGET, HAND_BUDGET, pending_hand_budget\n        )\n    ]\n    mandatory_steps = sum(len(task.actions) for task in schedulable_required)\n    mandatory_steps += len({\n        item\n        for task in schedulable_required\n        for item, amount in task.needs.items()\n        if amount > 0\n    })\n\n    candidates = []\n    last_unassigned = list(tasks)\n    for count in range(minimum, max_hands + 1):\n        starts = [tuple(farmer_start)] + predicted_hand_starts(\n            farmer_start, existing_hand_starts, count\n        )\n        budgets = [FARMER_BUDGET]\n        budgets += [HAND_BUDGET] * min(count, len(existing_hand_starts))\n        budgets += [pending_hand_budget] * max(\n            0, count - len(existing_hand_starts)\n        )\n        if count < max_hands and sum(budgets) < mandatory_steps:\n            continue\n\n        _, unassigned = _pack(tasks, starts, budgets, shed_access)\n        last_unassigned = unassigned\n        if marginal_hire_costs is None and not unassigned:\n            return count, []\n        candidates.append((count, unassigned))\n\n    if not candidates:\n        return minimum, last_unassigned\n    if marginal_hire_costs is None:\n        return candidates[-1]\n\n    required_missing = [\n        sum(task.mandatory is not False for task in missing)\n        for _, missing in candidates\n    ]\n    best_required = min(required_missing)\n\n    # If the hard constraints are impossible even at the best headcount, do\n    # not pay for extra hands that fail to improve feasibility.\n    if best_required:\n        index = required_missing.index(best_required)\n        return candidates[index]\n\n    base_index = required_missing.index(0)\n    base_count, base_missing = candidates[base_index]\n    total_optional_value = sum(\n        task.value for task in tasks if task.mandatory is False\n    )\n\n    def admitted_optional_value(missing):\n        return total_optional_value - sum(\n            task.value for task in missing if task.mandatory is False\n        )\n\n    chosen_count, chosen_missing = base_count, base_missing\n    best_net = admitted_optional_value(base_missing)\n\n    for index in range(base_index + 1, len(candidates)):\n        if required_missing[index]:\n            continue\n        count, missing = candidates[index]\n        extra_hire_cost = sum(\n            marginal_hire_costs[\n                base_count - minimum : count - minimum\n            ]\n        )\n        net = admitted_optional_value(missing) - extra_hire_cost\n        if net > best_net:\n            chosen_count, chosen_missing, best_net = count, missing, net\n\n    return chosen_count, chosen_missing\n\n\ndef _rebalance_feed(buckets, starts, budgets, shed_access, tasks):\n    """Consolidate WHEAT pickups without changing task inclusion or priorities.\n\n    A task may move to any feasible insertion point.  The optimization looks\n    only at complete-route length, terminal feasibility, and the number of\n    workers that need a WHEAT pickup.\n    """\n    terminal = any(task.terminal_day or task.cashout for task in tasks)\n\n    def uses_wheat(task):\n        return task.needs.get("WHEAT", 0) > 0 and not task.immediate_drop\n\n    def metrics(worker, bucket):\n        length = _task_length(\n            starts[worker],\n            bucket,\n            lambda position: nearest_shed(position, shed_access),\n        )\n        if not bucket:\n            return length, 0, 0\n        late = int(\n            length > _bucket_budget(budgets[worker], bucket, terminal)\n        )\n        carriers = int(any(uses_wheat(task) for task in bucket))\n        return length, late, carriers\n\n    for _ in range(2):\n        changed = False\n        for source in range(len(buckets) - 1, -1, -1):\n            for task in list(buckets[source]):\n                if not uses_wheat(task):\n                    continue\n                index = buckets[source].index(task)\n                remaining = buckets[source][:index] + buckets[source][index + 1 :]\n                old_source = metrics(source, buckets[source])\n                new_source = metrics(source, remaining)\n                best = None\n                for target in range(len(buckets)):\n                    if source == target or not any(\n                        uses_wheat(other) for other in buckets[target]\n                    ):\n                        continue\n                    old_target = metrics(target, buckets[target])\n                    for insertion in range(len(buckets[target]) + 1):\n                        merged = (\n                            buckets[target][:insertion]\n                            + [task]\n                            + buckets[target][insertion:]\n                        )\n                        new_target = metrics(target, merged)\n                        if new_target[1]:\n                            continue\n                        if (\n                            new_source[1] + new_target[1]\n                            > old_source[1] + old_target[1]\n                        ):\n                            continue\n                        delta_steps = (\n                            new_source[0] + new_target[0]\n                            - old_source[0] - old_target[0]\n                        )\n                        delta_carriers = (\n                            new_source[2] + new_target[2]\n                            - old_source[2] - old_target[2]\n                        )\n                        score = delta_steps + 4 * delta_carriers\n                        candidate = (score, target, insertion, merged)\n                        if score < 0 and (\n                            best is None or candidate[:3] < best[:3]\n                        ):\n                            best = candidate\n                if best is not None:\n                    _, target, _insertion, merged = best\n                    buckets[source], buckets[target] = remaining, merged\n                    changed = True\n        if not changed:\n            break\n    return buckets\n'

text = text[:start] + replacement + "\n\n" + text[end + 1:]
path.write_text(text)
